INSERT INTO `Roster` VALUES ('AYHNm','E5iaZj0J',0,'The Cult of the Blade','TYR','WB24','','',1,2,2,0,1,1,0,307,0,'','','',0,NULL,NULL,NULL,'2024-11-01 18:44:12'),('AYHNm','ogAa8mlG',1,'Dork Angels','IMP','AOD','','',1,2,2,0,0,1,0,55,0,'','','',0,NULL,NULL,NULL,'2024-10-30 12:55:41'),('ElJ61','tGt5juk4',0,'Sample Team: Intercessors','IMP','AOD','Led by Brother-Sergeant Cybus, the Intercessors are a squad of versatile and seasoned warriors whose victories are as numerous as they are exemplary.','',1,3,2,0,0,0,0,0,0,'','','',0,NULL,NULL,NULL,'2024-11-12 20:28:03'),('prebuilt','2e1xa42O',2,'Strike Force Justian','IMP','AOD','Strike Force Justian stands as an elite and unwavering arm of the Ultramarines Chapter, under the resolute leadership of Captain Justian. Renowned for their unwavering commitment to honor, duty, and the Codex Astartes, this formidable strike force exemplifies the finest traditions of the Chapter.','',1,3,2,0,0,1,1,330,28,'','','',0,'','','','2024-10-13 18:35:23'),('prebuilt','9HXAL6Q4',19,'Target Primus 21','HBR','AEF','We do not determine the guilty; we do not decide the punishment; we are merely the cold instruments of the Emperor\'s vengeance.\r There is no form of Death unknown to us; there is no form of Terror beyond our means; there is no enemy outside our reach.\r We are the blade that hovers over the throat of the traitor; we are the bullet that awaits the heretic\'s skull; we are the poison in the throat of the alien.','',1,3,2,0,0,0,0,444,70,'','','',0,NULL,NULL,NULL,'2024-02-06 22:38:56'),('prebuilt','aNLcdHAr',1,'Angels Of Death','IMP','AOD','Led by Brother-Sergeant Cybus, the Intercessors are a squad of versatile and seasoned warriors whose victories are as numerous as they are exemplary.','',1,3,2,0,0,0,0,513,2612,'','','',0,NULL,NULL,NULL,'2024-10-13 17:37:16'),('prebuilt','cBYqgF6R',5,'Phobos','IMP','PHO24','Sergeant Joreas Dreadfang\'s Bladereach Squad is an elite force of Space Marines renowned for their unmatched stealth and precision in carrying out covert operations, operating in the shadows, and striking terror into the hearts of their enemies across the Galaxy.','BladeReach',1,3,2,0,0,0,1,106,18,'','','',0,NULL,NULL,NULL,'2024-10-13 18:35:50'),('prebuilt','Hb3k2Omv',8,'The Pallid Hand','CHAOS','PM24','','',1,2,0,0,0,0,0,51,8,'','','',0,NULL,NULL,NULL,'2024-11-06 11:44:54'),('prebuilt','IZKvD',17,'Convenant Of Hate 21','CHAOS','CULT','','',1,4,2,0,0,0,0,879,182,'','','',0,NULL,NULL,NULL,'2023-05-23 11:22:14'),('prebuilt','PB-AMVP',11,'Voss Prime 21','IMP','HC','','',1,0,2,0,0,0,0,2452,213,'',NULL,NULL,0,NULL,NULL,NULL,'2022-11-23 15:27:55'),('prebuilt','PB-CSMFS',16,'Faithless Scourge 21','CHAOS','CSM','','',1,0,2,0,0,0,0,1129,131,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:51'),('prebuilt','PB-DWTS',6,'Talon Squad 21','IMP','SM','DeathWatch Talon Squad is an elite group made up of best Space Marines veterans from across the Chapters, trained to become the ultimate tools in one of the Imperium\'s holiest missions: the extermination of the xenos, the alien. Utilising the most advanced technology in the Imperium and receiving specialist instruction in the strengths and weaknesses of their foes, Talon Squad works under the Ordo Xenos of the Imperial Inquisition in order to hunt down and destroy the most dangerous xenos threats in the galaxy.','',1,2,2,0,0,0,0,2154,119,'',NULL,NULL,0,NULL,NULL,NULL,'2022-11-26 17:29:14'),('prebuilt','PB-ECC',13,'Nuns With Guns 21','IMP','ECC','The Sisters of the Order Of Our Martyred Lady have determination beyond even their fellow Sisters of the other orders, forever driven to avenge the death of Katherine and their Sisters who fall in battle. To their enemies, they are not known for mercy, but instead for thorough and utter destructiveness. ','',1,0,2,0,0,0,0,2635,246,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:50'),('prebuilt','PB-ESS',14,'Elucidian Starstriders 21','IMP','ESS','Elucia Vhane is a scion of a noble mercantile dynasty. Leaving behind her family\'s operations in the\n galactic North, Vhane led her Elucidian Starstriders to the Eastern Fringe.\n There, the bold Rogue Trader seeks to eclipse the rich history of her ancestors with her own rise to glory - or die trying.','',1,2,2,0,0,0,0,1348,381,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:47'),('prebuilt','PB-GK',15,'Consecrators 21','IMP','GK','The Grey Knights act as the military arm or \"Chamber Militant\" of the Ordo Malleus, the Daemonhunters who form the oldest branch of the virtually omnipotent Inquisition. The Grey Knights\' fortress-monastery, the Citadel of Titan, is based on Titan, the largest of the moons of the gas giant Saturn in the Sol System. It is kept as a private preserve of the Inquisition. ','',1,2,2,0,0,0,0,2002,188,'',NULL,NULL,0,NULL,NULL,NULL,'2022-11-26 16:39:26'),('prebuilt','PB-GPI',9,'Gellerpox Infected 21','CHAOS','GPI','Corrupted by a gruesome techno-organic affiction, the Gellerpox Infected are nightmarish meldings of flesh, machinery, and rampant disease. Most of these hideous beings began as loyal servants of the God Emperor. Those origins are long gone, wiped away by supematural sickness and a compulsion to spread their infection across the Stars.','',1,2,2,0,0,0,0,1603,469,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:47'),('prebuilt','PB-INTS',7,'Intercessors 21','IMP','INTS','Led by Brother-Sergeant Cybus, the Intercessors are a squad of versatile and seasoned warriors whose victories are as numerous as they are exemplary. ','',1,0,2,0,0,0,0,3757,38014,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:26'),('prebuilt','PB-NECTW',12,'Papa\'s Necronios 21','NEC','TW','','',1,0,2,0,0,0,0,1268,104,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:50'),('prebuilt','PB-PHO',8,'Phobos 21','IMP','PHO','Elite killers, saboteurs, and terror troops who spread fear and ruin throughout the enemy\'s domain, Brother-Sergeant Joreas Dreadfang\'s Phobos squad leaves no trace - and no survivors. ','',1,0,2,0,0,0,0,2627,289,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 16:01:32'),('prebuilt','PB-SFJ',18,'Strike Force Justian 21','IMP','SFJ','Strike Force Justian stands as an elite and unwavering arm of the Ultramarines Chapter, under the resolute leadership of Captain Justian. Renowned for their unwavering commitment to honor, duty, and the Codex Astartes, this formidable strike force exemplifies the finest traditions of the Ultramarines. ','',1,4,2,0,0,0,0,974,240,'','','',0,NULL,NULL,NULL,'2023-09-06 14:11:32'),('prebuilt','PB-VGSHOV',10,'Shovel Squad 21','IMP','VG','','',1,0,2,0,0,0,0,2521,451,'',NULL,NULL,0,NULL,NULL,NULL,'2022-10-28 14:34:54'),('prebuilt','Rjl1fwcP',4,'Elucidian Starstriders','IMP','ESS24','','',1,3,2,0,0,0,0,40,37,'','','',0,NULL,NULL,NULL,'2024-10-14 05:46:39'),('prebuilt','rUqsW9FL',0,'Voss Prime','IMP','HC24','','',1,3,2,0,0,0,0,79,12,'','','',0,NULL,NULL,NULL,'2024-10-31 08:34:48'),('prebuilt','XiJHPvXf',3,'Kommandos','ORK','KOM24','The Throat Slittaz epitomize the brutal and cunning nature of Ork Kommandos, led by the fearsome Boss Graxnuhk. This squad of Ork guerrilla warriors is renowned for their savage close-quarters combat skills and their relentless thirst for bloodshed. Boss Graxnuhk leads the squad with an iron fist, instilling a sense of loyalty and fearlessness in his followers.','BAD MOON',1,4,2,0,0,0,1,201,96,'','','',0,NULL,NULL,NULL,'2024-10-13 18:34:37'),('vince','BR',2,'BladeReach','IMP','PHO24','Sergeant Joreas Dreadfang\'s Bladereach Squad is an elite force of Space Marines renowned for their unmatched stealth and precision in carrying out covert operations, operating in the shadows, and striking terror into the hearts of their enemies across the Galaxy.','BladeReach',2,2,2,0,1,1,1,3961,48,'','','',0,NULL,NULL,NULL,'2024-10-13 18:02:09'),('vince','CLAM',7,'Clamor Mortis 21','CHAOS','DAEM','A sinister warband of Chaos Daemonesses, Clamor Mortis revels in the seductive allure of corruption and eternal damnation. Led by their enigmatic and malevolent Alluress Araqhne, their every move is guided by the whims of the Dark Gods. United in their unholy sisterhood, they unleash arcane rituals, sow discord among their enemies, and reap souls for the glory of Chaos.','',1,4,2,0,1,1,1,1374,3,'','','',0,NULL,NULL,NULL,'2022-10-30 22:18:42'),('vince','Cynwl',4,'Desert Specters','IMP','AOD','Toland Strak\'s Desert Spectres stand as an elite force of Space Marines renowned for their exceptional prowess in desert warfare. Donning heat-resistant power armor adorned with intricate sand-resistant plating, the Desert Spectres blend seamlessly with their surroundings, rendering them nearly invisible to the untrained eye.','',1,3,2,0,1,1,1,4047,41,'','','',0,NULL,NULL,NULL,'2024-10-13 18:12:23'),('vince','INTER',5,'Interdictors 21','IMP','SM','The Interdictors stand as a vanguard of the Deathwatch, an elite squad led by the indomitable Remus Steelhand. These exceptional Space Marines are handpicked from various chapters, representing a formidable force united in the pursuit of eliminating xenos threats. Renowned for their adaptability and tactical versatility, the Interdictors demonstrate seamless coordination and lethal precision on the battlefield.','',1,4,2,0,1,1,1,1676,20,'','','',0,NULL,NULL,NULL,'2022-10-28 14:29:10'),('vince','JgHiM',0,'Whispering Scythes','IMP','AOD','The Whispering Scythes, a legendary squad of Space Marines, strikes fear into the hearts of their adversaries across the Cosmos. With their relentless dedication to the pursuit of justice and the protection of the innocent, they embody a potent combination of strength and resilience, making them an unstoppable force that strikes swiftly and decisively, leaving their enemies devastated in the wake of their divine fury.','',1,2,2,0,1,1,1,3767,13,'','','',0,NULL,NULL,NULL,'2024-10-13 17:47:52'),('vince','TCJUXO5o',1,'Strike Force Celestine','IMP','AOD','Strike Force Celestine stands as an elite and unwavering arm of the Raven Guard Chapter, under the resolute leadership of Captain Celestine. Renowned for their unwavering commitment to honor, duty, and the Codex Astartes, this formidable strike force exemplifies the finest traditions of the Chapter.','',1,2,2,0,1,1,1,615,9,'','','',0,'','','','2024-10-13 17:53:01'),('vince','VOX',6,'Vox Belli 21','IMP','ECC','Vox Belli, an elite squad of Sisters of Battle, marches forth under the unwavering guidance of Sister Superior Ellael. Clad in their iconic power armor adorned with sacred symbols, the squad exudes an aura of righteousness and unwavering faith. With their faith as their shield and the Emperor\'s will as their guiding light, Vox Belli stands as a shining beacon of purity and righteous fury.','',1,3,2,0,1,1,1,2852,19,'','','',0,NULL,NULL,NULL,'2022-11-01 04:46:55'),('vince','YveOp',3,'Throat Slittaz','ORK','KOM24','The Throat Slittaz epitomize the brutal and cunning nature of Ork Kommandos, led by the fearsome Boss Graxnuhk. This squad of Ork guerrilla warriors is renowned for their savage close-quarters combat skills and their relentless thirst for bloodshed. Boss Graxnuhk leads the squad with an iron fist, instilling a sense of loyalty and fearlessness in his followers.','BAD MOON',1,4,2,0,1,1,1,3732,318,'','','',0,NULL,NULL,NULL,'2024-10-13 18:06:47');
